from utils.common_methods import get_test_data

class UserService:
    def __init__(self, request): self.request = request
    def get_users(self):
        response = self.request.get(f"{get_test_data().get('apiBaseUrl', 'https://jsonplaceholder.typicode.com')}/users")
        return {"status": response.status, "headers": response.headers, "body": response.json()}
    def request_users(self): self.users_response = self.get_users()
    def verify_users_response(self):
        response = getattr(self, "users_response", None)
        if not response or response["status"] != get_test_data()["apiExpectedStatus"] or not response["body"]:
            raise AssertionError("Users response was not successful")
    def verify_users_available(self):
        self.request_users()
        self.verify_users_response()
